cypress_script:
describe('Notification Messages Test', () => {
  it('should display a notification message when the link is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('#flash-messages').should('not.exist');
    cy.get('a[href="/notification_message"]').click();
    cy.get('#flash-messages').should('be.visible');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/notification_message_rendered');
  });

  it('should not display a notification message before the link is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('#flash-messages').should('not.exist');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/notification_message_rendered');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Notification Messages Test', () => {
  test('should display a notification message when the link is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await expect(page.locator('#flash-messages')).toBeHidden();
    await page.click('a[href="/notification_message"]');
    await expect(page.locator('#flash-messages')).toBeVisible();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  test('should not display a notification message before the link is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await expect(page.locator('#flash-messages')).toBeHidden();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/notification_message_rendered');
  });
});
